  // Pengacak otomatis soal & posisi opsi (A/B/C/D) setiap kali siswa membuka sesi
  if (!window.__SHUFFLE_HOOKED__) {
    window.__SHUFFLE_HOOKED__ = true;
    const acakArray = (arr) => {
      const a = [...arr];
      for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
      }
      return a;
    };
    window.getSoalAcak = function(kunci) {
      const bank = (window.BANK_SOAL_MASTER && window.BANK_SOAL_MASTER[kunci]) || [];
      return acakArray(bank).map(item => {
        const jawabanBenar = item.p[item.b];
        const opsiAcak = acakArray(item.p);
        return {
          q: item.q,
          p: opsiAcak,
          b: opsiAcak.indexOf(jawabanBenar),
          bahas: item.bahas
        };
      });
    };
  }
